#!/usr/bin/env bash
set -euo pipefail

RLINF_ROOT="${RLINF_ROOT:-/data/Xixixi/VLA1/RLinf}"
PI0_MODEL="${PI0_MODEL:-/data/Xixixi/VLA1/model_cache/openpi/openpi-assets/checkpoints/pi0_libero_pytorch}"

# Supported:
#   adapter_only
#   adapter_action_head
#   adapter_action_expert
#   adapter_action_head_action_expert
EXPERIMENT_VARIANT="${EXPERIMENT_VARIANT:-adapter_action_head}"

TRAIN_BASE_ROOT="${TRAIN_BASE_ROOT:-\
${RLINF_ROOT}/results/pi0/adapter_ppo/libero_goal_ppo_pi0_visual_adapter}"

# Compatible with the directory structure generated by the new training script:
#   TRAIN_BASE_ROOT/EXPERIMENT_VARIANT/timestamp/experiment/checkpoints/...
TRAIN_RUN_ROOT="${TRAIN_RUN_ROOT:-\
${TRAIN_BASE_ROOT}/${EXPERIMENT_VARIANT}}"

# Setting this explicitly bypasses automatic checkpoint discovery.
ADAPTER_CKPT="${ADAPTER_CKPT:-}"

CATEGORY="${CATEGORY:-Objects Layout}"
CLASSIFICATION_PATH="${CLASSIFICATION_PATH:-\
/data/Xixixi/VLA1/LIBERO-plus/libero/libero/benchmark/task_classification.json}"

# EVAL_ALL=0: smoke, NUM_ENVS tasks for one rollout epoch.
# EVAL_ALL=1: traverse the complete category.
EVAL_ALL="${EVAL_ALL:-1}"
NUM_ENVS="${NUM_ENVS:-25}"
ROLLOUT_EPOCH="${ROLLOUT_EPOCH:-17}"

SEED="${SEED:-7}"
SAVE_VIDEO="${SAVE_VIDEO:-false}"

ADAPTER_DIM="${ADAPTER_DIM:-64}"
ADAPTER_DROPOUT="${ADAPTER_DROPOUT:-0.0}"
ADAPTER_RESIDUAL_SCALE="${ADAPTER_RESIDUAL_SCALE:-1.0}"

export MUJOCO_GL="${MUJOCO_GL:-egl}"
export PYOPENGL_PLATFORM="${PYOPENGL_PLATFORM:-egl}"
export MUJOCO_EGL_DEVICE_ID="${MUJOCO_EGL_DEVICE_ID:-0}"
export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-0}"

export PYTHONUNBUFFERED=1
export HYDRA_FULL_ERROR=1
export ROBOT_PLATFORM=LIBERO

export LIBERO_TYPE=plus
export LIBERO_CATEGORY="${CATEGORY}"
export LIBERO_CLASSIFICATION_PATH="${CLASSIFICATION_PATH}"

unset LIBERO_PERTURBATION || true
unset LIBERO_SUFFIX || true

cd "${RLINF_ROOT}"

case "${EXPERIMENT_VARIANT}" in
  adapter_only | \
  adapter_action_head | \
  adapter_action_expert | \
  adapter_action_head_action_expert)
    ;;
  *)
    echo "ERROR: unsupported EXPERIMENT_VARIANT:" >&2
    echo "  ${EXPERIMENT_VARIANT}" >&2
    exit 1
    ;;
esac

test -s "${PI0_MODEL}/model.safetensors"
test -s "${PI0_MODEL}/config.json"
test -s \
  "${PI0_MODEL}/assets/physical-intelligence/libero/norm_stats.json"

test -s "${CLASSIFICATION_PATH}"
test -s \
  "evaluations/libero/libero_goal_pi0_visual_adapter_eval.yaml"

# ============================================================
# Locate checkpoint
# ============================================================

if [[ -z "${ADAPTER_CKPT}" ]]; then
  if [[ ! -d "${TRAIN_RUN_ROOT}" ]]; then
    echo "ERROR: training result directory does not exist:" >&2
    echo "  ${TRAIN_RUN_ROOT}" >&2
    echo "Set TRAIN_RUN_ROOT or ADAPTER_CKPT explicitly." >&2
    exit 1
  fi

  ADAPTER_CKPT="$(
    find "${TRAIN_RUN_ROOT}" \
      -type f \
      -path "*/actor/trainable_model_state_dict/trainable_weights.pt" \
      | sort -V \
      | tail -n 1
  )"
fi

if [[ -z "${ADAPTER_CKPT}" || ! -s "${ADAPTER_CKPT}" ]]; then
  echo "ERROR: trainable_weights.pt was not found." >&2
  echo "TRAIN_RUN_ROOT=${TRAIN_RUN_ROOT}" >&2
  echo "ADAPTER_CKPT=${ADAPTER_CKPT}" >&2
  exit 1
fi

export ADAPTER_CKPT

# ============================================================
# Inspect checkpoint and detect training variant
# ============================================================

mapfile -t CKPT_INFO < <(
python - <<'PY'
import os
import torch

path = os.environ["ADAPTER_CKPT"]

payload = torch.load(
    path,
    map_location="cpu",
    weights_only=True,
)

state = payload.get("state_dict", payload)

if not isinstance(state, dict) or not state:
    raise RuntimeError(f"Invalid checkpoint state_dict: {path}")

adapter_keys = [
    key
    for key in state
    if "visual_last_layer_adapter" in key
]

value_keys = [
    key
    for key in state
    if "value_head" in key
]

action_expert_keys = [
    key
    for key in state
    if "gemma_expert" in key
]

action_head_module_names = (
    "action_in_proj",
    "action_out_proj",
    "state_proj",
    "action_time_mlp",
    "action_time_mlp_in",
    "action_time_mlp_out",
    "time_mlp_in",
    "time_mlp_out",
)

action_head_keys = [
    key
    for key in state
    if any(name in key for name in action_head_module_names)
]

if not adapter_keys:
    raise RuntimeError(
        "Checkpoint does not contain visual_last_layer_adapter "
        f"parameters: {path}"
    )

has_action_head = bool(action_head_keys)
has_action_expert = bool(action_expert_keys)

if has_action_head and has_action_expert:
    variant = "adapter_action_head_action_expert"
elif has_action_head:
    variant = "adapter_action_head"
elif has_action_expert:
    variant = "adapter_action_expert"
else:
    variant = "adapter_only"

parameter_count = sum(
    value.numel()
    for value in state.values()
    if isinstance(value, torch.Tensor)
)

print(payload.get("global_step", "unknown"))
print(variant)
print(len(state))
print(len(adapter_keys))
print(len(action_head_keys))
print(len(action_expert_keys))
print(len(value_keys))
print(parameter_count)
PY
)

if (( ${#CKPT_INFO[@]} != 8 )); then
  echo "ERROR: failed to inspect checkpoint metadata." >&2
  exit 1
fi

CKPT_STEP="${CKPT_INFO[0]}"
DETECTED_VARIANT="${CKPT_INFO[1]}"
SAVED_TENSORS="${CKPT_INFO[2]}"
ADAPTER_TENSORS="${CKPT_INFO[3]}"
ACTION_HEAD_TENSORS="${CKPT_INFO[4]}"
ACTION_EXPERT_TENSORS="${CKPT_INFO[5]}"
VALUE_HEAD_TENSORS="${CKPT_INFO[6]}"
SAVED_PARAMETERS="${CKPT_INFO[7]}"

if [[ "${DETECTED_VARIANT}" != "${EXPERIMENT_VARIANT}" ]]; then
  echo "ERROR: checkpoint does not match requested experiment." >&2
  echo "Requested: ${EXPERIMENT_VARIANT}" >&2
  echo "Detected:  ${DETECTED_VARIANT}" >&2
  echo "Checkpoint: ${ADAPTER_CKPT}" >&2
  exit 1
fi

# ============================================================
# Count category tasks
# ============================================================

export CATEGORY
export CLASSIFICATION_PATH

TASK_COUNT="$(
python - <<'PY'
import json
import os

path = os.environ["CLASSIFICATION_PATH"]
category = os.environ["CATEGORY"].strip().casefold()
suite = "libero_goal"

with open(path, "r", encoding="utf-8") as file:
    manifest = json.load(file)

selected = [
    entry
    for entry in manifest[suite]
    if str(entry.get("category", "")).strip().casefold()
    == category
]

names = {
    str(entry["name"]).removesuffix(".bddl")
    for entry in selected
}

print(len(names))
PY
)"

if (( TASK_COUNT <= 0 )); then
  echo "ERROR: no tasks selected for category '${CATEGORY}'" >&2
  exit 1
fi

if [[ "${EVAL_ALL}" == "1" ]]; then
  ROLLOUT_EPOCH=$(( (TASK_COUNT + NUM_ENVS - 1) / NUM_ENVS ))
fi

CATEGORY_TAG="${CATEGORY// /_}"

LOG_ROOT="${LOG_ROOT:-\
${TRAIN_BASE_ROOT}/${DETECTED_VARIANT}/${CATEGORY_TAG}/step_${CKPT_STEP}}"

EXPERIMENT_NAME="${EXPERIMENT_NAME:-\
pi0_${DETECTED_VARIANT}_${CATEGORY_TAG}_step_${CKPT_STEP}}"

echo "============================================================"
echo "PI0_MODEL=${PI0_MODEL}"
echo "ADAPTER_CKPT=${ADAPTER_CKPT}"
echo "Requested variant=${EXPERIMENT_VARIANT}"
echo "Detected variant=${DETECTED_VARIANT}"
echo "Global step=${CKPT_STEP}"
echo "Saved tensors=${SAVED_TENSORS}"
echo "Adapter tensors=${ADAPTER_TENSORS}"
echo "Action-head tensors=${ACTION_HEAD_TENSORS}"
echo "Action-expert tensors=${ACTION_EXPERT_TENSORS}"
echo "Value-head tensors=${VALUE_HEAD_TENSORS}"
echo "Saved parameters=${SAVED_PARAMETERS}"
echo "CATEGORY=${CATEGORY}"
echo "TASK_COUNT=${TASK_COUNT}"
echo "NUM_ENVS=${NUM_ENVS}"
echo "ROLLOUT_EPOCH=${ROLLOUT_EPOCH}"
echo "EVAL_ALL=${EVAL_ALL}"
echo "EXPERIMENT_NAME=${EXPERIMENT_NAME}"
echo "LOG_ROOT=${LOG_ROOT}"
echo "============================================================"

if [[ "${RESET_RAY:-1}" == "1" ]]; then
  ray stop --force >/dev/null 2>&1 || true
fi

LOG_ROOT="${LOG_ROOT}" \
bash evaluations/run_eval.sh \
  libero \
  libero_goal_pi0_visual_adapter_eval \
  "rollout.model.model_path=${PI0_MODEL}" \
  "rollout.model.trainable_checkpoint_path=${ADAPTER_CKPT}" \
  "rollout.model.add_value_head=false" \
  "rollout.model.openpi.train_expert_only=true" \
  "rollout.model.openpi.train_action_expert=false" \
  "rollout.model.openpi.train_action_head=false" \
  "rollout.model.openpi.visual_adaptation.backbone.type=last_layer_adapter" \
  "rollout.model.openpi.visual_adaptation.backbone.last_layer_adapter.bottleneck_dim=${ADAPTER_DIM}" \
  "rollout.model.openpi.visual_adaptation.backbone.last_layer_adapter.dropout=${ADAPTER_DROPOUT}" \
  "rollout.model.openpi.visual_adaptation.backbone.last_layer_adapter.residual_scale=${ADAPTER_RESIDUAL_SCALE}" \
  "rollout.model.openpi.visual_adaptation.ftm.enabled=false" \
  "rollout.model.openpi.noise_method=flow_ode" \
  "rollout.model.openpi.noise_level=0.0" \
  "runner.logger.experiment_name=${EXPERIMENT_NAME}" \
  "env.eval.seed=${SEED}" \
  "env.eval.group_size=1" \
  "env.eval.total_num_envs=${NUM_ENVS}" \
  "env.eval.rollout_epoch=${ROLLOUT_EPOCH}" \
  "env.eval.max_episode_steps=300" \
  "env.eval.max_steps_per_rollout_epoch=300" \
  "env.eval.video_cfg.save_video=${SAVE_VIDEO}"